<script setup>import { onMounted, ref } from "vue"; import AdminLayout from "../../layouts/AdminLayout.vue"; import { auditService } from "../../services/api"; const items = ref([]), error = ref(""); onMounted(async () => { try { items.value = (await auditService.list()).data; } catch (exception) { error.value = exception.message; } });</script><template><AdminLayout><section class="p-5 md:p-10"><h1 class="text-3xl font-bold">Journal d'audit</h1><p class="mt-2 text-slate-500">Traçabilité des actions administratives enregistrées.</p><div v-if="error" class="alert alert-error mt-6">{{ error }}</div><div v-else class="mt-7 overflow-x-auto rounded-2xl bg-white shadow-sm"><table class="table"><thead><tr><th>Administrateur</th><th>Action</th><th>Cible</th><th>ID</th><th>Détails</th><th>Date</th></tr></thead><tbody><tr v-for="item in items" :key="item.id"><td>#{{ item.administrateur_id }}</td><td><code class="text-xs">{{ item.action }}</code></td><td>{{ item.type_cible }}</td><td>{{ item.cible_id }}</td><td>{{ item.details || '—' }}</td><td>{{ new Date(item.date_creation).toLocaleString('fr-FR') }}</td></tr><tr v-if="!items.length"><td colspan="6" class="py-10 text-center text-slate-500">Aucun journal d'audit.</td></tr></tbody></table></div></section></AdminLayout></template>
